1	package com.example.starter.metro;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.sql.Statement;
6	import java.sql.Timestamp;
7	import java.time.LocalDate;
8	import java.time.LocalDateTime;
9	import java.util.List;
10	import java.util.Optional;
11	
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.jdbc.core.RowMapper;
15	import org.springframework.jdbc.support.GeneratedKeyHolder;
16	import org.springframework.jdbc.support.KeyHolder;
17	import org.springframework.stereotype.Repository;
18	
19	/**
20	 * 清分数据访问：交易流水、幂等记录、清分批次、清分明细与对账差异。
21	 */
22	@Repository
23	public class MetroRepository {
24	
25	    private final JdbcTemplate jdbcTemplate;
26	
27	    public MetroRepository(JdbcTemplate jdbcTemplate) {
28	        this.jdbcTemplate = jdbcTemplate;
29	    }
30	
31	    private static final RowMapper<TxnRow> TXN_MAPPER = (rs, rowNum) -> new TxnRow(
32	            rs.getLong("id"),
33	            rs.getString("txn_no"),
34	            rs.getString("card_id"),
35	            rs.getString("entry_station"),
36	            rs.getTimestamp("entry_time").toLocalDateTime(),
37	            rs.getString("exit_station"),
38	            toDateTime(rs, "exit_time"),
39	            rs.getString("status"),
40	            toLong(rs, "distance_m"),
41	            rs.getLong("chain_base_m"),
42	            toLong(rs, "fare_cents"),
43	            rs.getLong("penalty_cents"),
44	            rs.getInt("transfer_flag") == 1,
45	            rs.getInt("estimated_flag") == 1,
46	            toLong(rs, "batch_id"),
47	            toDate(rs, "biz_date"),
48	            rs.getString("request_id"),
49	            rs.getString("fingerprint"));
50	
51	    private static final RowMapper<BatchRow> BATCH_MAPPER = (rs, rowNum) -> new BatchRow(
52	            rs.getLong("id"),
53	            rs.getDate("biz_date").toLocalDate(),
54	            rs.getString("status"),
55	            rs.getLong("total_cents"),
56	            rs.getInt("txn_count"),
57	            rs.getString("seal_request_id"),
58	            toDateTime(rs, "sealed_at"));
59	
60	    private static final RowMapper<DetailRow> DETAIL_MAPPER = (rs, rowNum) -> new DetailRow(
61	            rs.getLong("id"),
62	            rs.getLong("batch_id"),
63	            rs.getString("txn_no"),
64	            rs.getString("line_code"),
65	            rs.getLong("distance_m"),
66	            rs.getBigDecimal("ratio").toPlainString(),
67	            rs.getLong("amount_cents"),
68	            rs.getString("entry_type"));
69	
70	    private static final RowMapper<DiscrepancyRow> DISCREPANCY_MAPPER = (rs, rowNum) -> new DiscrepancyRow(
71	            rs.getLong("id"),
72	            rs.getDate("biz_date").toLocalDate(),
73	            rs.getString("txn_no"),
74	            rs.getLong("amount_cents"),
75	            rs.getString("reason"));
76	
77	    private static final RowMapper<IdemRow> IDEM_MAPPER = (rs, rowNum) -> new IdemRow(
78	            rs.getString("scope"),
79	            rs.getString("request_id"),
80	            rs.getString("fingerprint"),
81	            rs.getString("response_body"));
82	
83	    private static LocalDateTime toDateTime(ResultSet rs, String column) throws SQLException {
84	        Timestamp ts = rs.getTimestamp(column);
85	        return ts == null ? null : ts.toLocalDateTime();
86	    }
87	
88	    private static Long toLong(ResultSet rs, String column) throws SQLException {
89	        long value = rs.getLong(column);
90	        return rs.wasNull() ? null : value;
91	    }
92	
93	    private static LocalDate toDate(ResultSet rs, String column) throws SQLException {
94	        java.sql.Date date = rs.getDate(column);
95	        return date == null ? null : date.toLocalDate();
96	    }
97	
98	    private static final String TXN_COLUMNS =
99	            "id, txn_no, card_id, entry_station, entry_time, exit_station, exit_time, status,"
100	            + " distance_m, chain_base_m, fare_cents, penalty_cents, transfer_flag, estimated_flag,"
101	            + " batch_id, biz_date, request_id, fingerprint";
102	
103	    /** 按流水号查询交易。 */
104	    public Optional<TxnRow> findTxnByNo(String txnNo) {
105	        List<TxnRow> rows = jdbcTemplate.query(
106	                "SELECT " + TXN_COLUMNS + " FROM metro_transaction WHERE txn_no = ?",
107	                TXN_MAPPER, txnNo);
108	        return rows.stream().findFirst();
109	    }
110	
111	    /** 按流水号查询交易并加行锁（SELECT ... FOR UPDATE）。 */
112	    public Optional<TxnRow> findTxnByNoForUpdate(String txnNo) {
113	        List<TxnRow> rows = jdbcTemplate.query(
114	                "SELECT " + TXN_COLUMNS + " FROM metro_transaction WHERE txn_no = ? FOR UPDATE",
115	                TXN_MAPPER, txnNo);
116	        return rows.stream().findFirst();
117	    }
118	
119	    /** 插入进闸交易，返回主键；流水号重复抛出 DuplicateKeyException。 */
120	    public long insertTxn(TxnRow row) {
121	        KeyHolder keyHolder = new GeneratedKeyHolder();
122	        LocalDateTime now = LocalDateTime.now();
123	        jdbcTemplate.update(connection -> {
124	            var ps = connection.prepareStatement(
125	                    "INSERT INTO metro_transaction (txn_no, card_id, entry_station, entry_time, status,"
126	                    + " chain_base_m, penalty_cents, transfer_flag, estimated_flag, request_id, fingerprint,"
127	                    + " created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
128	                    Statement.RETURN_GENERATED_KEYS);
129	            ps.setString(1, row.txnNo());
130	            ps.setString(2, row.cardId());
131	            ps.setString(3, row.entryStation());
132	            ps.setTimestamp(4, Timestamp.valueOf(row.entryTime()));
133	            ps.setString(5, row.status());
134	            ps.setLong(6, row.chainBaseM());
135	            ps.setLong(7, row.penaltyCents());
136	            ps.setInt(8, row.transfer() ? 1 : 0);
137	            ps.setInt(9, row.estimated() ? 1 : 0);
138	            ps.setString(10, row.requestId());
139	            ps.setString(11, row.fingerprint());
140	            ps.setTimestamp(12, Timestamp.valueOf(now));
141	            ps.setTimestamp(13, Timestamp.valueOf(now));
142	            return ps;
143	        }, keyHolder);
144	        return keyHolder.getKey().longValue();
145	    }
146	
147	    /** 出闸/暂记/补登后更新交易结算字段。 */
148	    public void updateTxnSettlement(TxnRow row) {
149	        jdbcTemplate.update(
150	                "UPDATE metro_transaction SET exit_station = ?, exit_time = ?, status = ?, distance_m = ?,"
151	                + " chain_base_m = ?, fare_cents = ?, penalty_cents = ?, transfer_flag = ?, estimated_flag = ?,"
152	                + " batch_id = ?, biz_date = ?, updated_at = ? WHERE id = ?",
153	                row.exitStation(),
154	                row.exitTime() == null ? null : Timestamp.valueOf(row.exitTime()),
155	                row.status(),
156	                row.distanceM(),
157	                row.chainBaseM(),
158	                row.fareCents(),
159	                row.penaltyCents(),
160	                row.transfer() ? 1 : 0,
161	                row.estimated() ? 1 : 0,
162	                row.batchId(),
163	                row.bizDate() == null ? null : java.sql.Date.valueOf(row.bizDate()),
164	                Timestamp.valueOf(LocalDateTime.now()),
165	                row.id());
166	    }
167	
168	    /** 查询票卡最近一次已有出闸时间的交易（用于换乘链判定）。 */
169	    public Optional<TxnRow> findLatestExitedTxnForCard(String cardId, LocalDateTime before) {
170	        List<TxnRow> rows = jdbcTemplate.query(
171	                "SELECT " + TXN_COLUMNS + " FROM metro_transaction"
172	                + " WHERE card_id = ? AND exit_time IS NOT NULL AND exit_time <= ?"
173	                + " ORDER BY exit_time DESC, id DESC LIMIT 1",
174	                TXN_MAPPER, cardId, Timestamp.valueOf(before));
175	        return rows.stream().findFirst();
176	    }
177	
178	    /** 按业务日期查询批次。 */
179	    public Optional<BatchRow> findBatchByDate(LocalDate bizDate) {
180	        List<BatchRow> rows = jdbcTemplate.query(
181	                "SELECT id, biz_date, status, total_cents, txn_count, seal_request_id, sealed_at"
182	                + " FROM clearing_batch WHERE biz_date = ?",
183	                BATCH_MAPPER, java.sql.Date.valueOf(bizDate));
184	        return rows.stream().findFirst();
185	    }
186	
187	    /** 按业务日期查询批次并加行锁。 */
188	    public Optional<BatchRow> findBatchByDateForUpdate(LocalDate bizDate) {
189	        List<BatchRow> rows = jdbcTemplate.query(
190	                "SELECT id, biz_date, status, total_cents, txn_count, seal_request_id, sealed_at"
191	                + " FROM clearing_batch WHERE biz_date = ? FOR UPDATE",
192	                BATCH_MAPPER, java.sql.Date.valueOf(bizDate));
193	        return rows.stream().findFirst();
194	    }
195	
196	    /** 创建 OPEN 批次，返回主键。 */
197	    public long insertBatch(LocalDate bizDate) {
198	        KeyHolder keyHolder = new GeneratedKeyHolder();
199	        jdbcTemplate.update(connection -> {
200	            var ps = connection.prepareStatement(
201	                    "INSERT INTO clearing_batch (biz_date, status, total_cents, txn_count, created_at)"
202	                    + " VALUES (?,?,?,?,?)",
203	                    Statement.RETURN_GENERATED_KEYS);
204	            ps.setDate(1, java.sql.Date.valueOf(bizDate));
205	            ps.setString(2, "OPEN");
206	            ps.setLong(3, 0L);
207	            ps.setInt(4, 0);
208	            ps.setTimestamp(5, Timestamp.valueOf(LocalDateTime.now()));
209	            return ps;
210	        }, keyHolder);
211	        return keyHolder.getKey().longValue();
212	    }
213	
214	    /** 插入清分明细。 */
215	    public void insertDetail(DetailRow row) {
