225	        // 出闸缺失：按 A 站最远站票价暂记（A->H 20 公里 -> 6 元）
226	        JsonNode estimate = postEstimate("r-m10", "T-E10", 200);
227	        assertEquals("ESTIMATED", estimate.get("status").asText());
228	        assertEquals(600L, estimate.get("fareCents").asLong());
229	        assertEquals(600L, getBatch("2026-09-25").get("totalCents").asLong());
230	
231	        // 补登出闸：同一事务内冲销暂记并按实结算（A->D 10 公里 4 元）
232	        JsonNode exit = postExit("r-x10", "T-E10", "D", "2026-09-25T09:20:00", 200);
233	        assertTrue(exit.get("compensated").asBoolean());
234	        assertEquals(400L, exit.get("fareCents").asLong());
235	
236	        JsonNode batch = getBatch("2026-09-25");
237	        // 不得双边计额：600 - 600 + 400 = 400
238	        assertEquals(400L, batch.get("totalCents").asLong());
239	        long estimateSum = 0;
240	        long reversalSum = 0;
241	        long settleSum = 0;
242	        for (JsonNode detail : batch.get("details")) {
243	            switch (detail.get("entryType").asText()) {
244	                case "ESTIMATE" -> estimateSum += detail.get("amountCents").asLong();
245	                case "REVERSAL" -> reversalSum += detail.get("amountCents").asLong();
246	                case "SETTLE" -> settleSum += detail.get("amountCents").asLong();
247	                default -> throw new IllegalStateException("unexpected type");
248	            }
249	        }
250	        assertEquals(600L, estimateSum);
251	        assertEquals(-600L, reversalSum);
252	        assertEquals(400L, settleSum);
253	    }
