255	    @Test
256	    void sealIsTerminalAndLateTransactionsGoToDiscrepancy() throws Exception {
257	        postEntry("r-e11a", "T-E11A", "CARD11", "A", "2026-09-25T09:00:00", 200);
258	        postExit("r-x11a", "T-E11A", "D", "2026-09-25T09:30:00", 200);
