262	        assertEquals(400L, seal.get("totalCents").asLong());
263	        assertTrue(!seal.get("replayed").asBoolean());
264	
265	        // 重复封账（同键重放与新键）均幂等成功，合计不变
266	        JsonNode resealSameKey = postSeal("r-s11", "2026-09-25", 200);
267	        assertTrue(resealSameKey.get("replayed").asBoolean());
268	        assertEquals(400L, resealSameKey.get("totalCents").asLong());
269	        JsonNode resealNewKey = postSeal("r-s11b", "2026-09-25", 200);
270	        assertEquals(400L, resealNewKey.get("totalCents").asLong());
271	
272	        // 封账后迟到交易：登记差异，不改已封账合计
