274	        JsonNode lateExit = postExit("r-x11b", "T-E11B", "D", "2026-09-25T23:30:00", 200);
275	        assertTrue(lateExit.get("lateDiscrepancy").asBoolean());
276	
277	        JsonNode batch = getBatch("2026-09-25");
