279	        assertEquals(1, batch.get("txnCount").asInt());
280	        JsonNode discrepancies = batch.get("discrepancies");
281	        assertEquals(1, discrepancies.size());
282	        assertEquals("T-E11B", discrepancies.get(0).get("txnNo").asText());
283	        assertEquals(200L, discrepancies.get(0).get("amountCents").asLong());
