/**
 * 按原线路实收份额分摊本次退款：
 * 先按份额向下取整并限制到各线路可退余额，剩余分逐一分给尚有可退余额的线路，
 * 按原份额降序、线路编号升序循环，直至分完。
 */
private Map<String, Long> allocateByOriginalShare(Map<String, OriginalShare> originals,
                                                  Map<String, Long> refundedByLine,
                                                  long refundCents) {
    long originalTotal = originals.values().stream().mapToLong(OriginalShare::amountCents).sum();
    List<String> order = originals.keySet().stream()
            .sorted(Comparator.<String>comparingLong(line -> originals.get(line).amountCents())
                    .reversed()
                    .thenComparing(Comparator.naturalOrder()))
            .toList();
    Map<String, Long> allocation = new LinkedHashMap<>();
    long assigned = 0L;
    for (String line : order) {
        long available = originals.get(line).amountCents()
                - refundedByLine.getOrDefault(line, 0L);
        long floor = refundCents * originals.get(line).amountCents() / originalTotal;
        long amount = Math.min(floor, available);
        allocation.put(line, amount);
        assigned += amount;
    }
    long remaining = refundCents - assigned;
    int cursor = 0;
    while (remaining > 0) {
        String line = order.get(cursor % order.size());
        cursor++;
        long available = originals.get(line).amountCents()
                - refundedByLine.getOrDefault(line, 0L);
        if (allocation.get(line) < available) {
            allocation.merge(line, 1L, Long::sum);
            remaining--;
        }
        if (cursor > order.size() * (refundCents + 1)) {
            throw new IllegalStateException("退款分摊无法收敛");
        }
    }
    return allocation;
}

